int frontend_parse_closure_capture_error(struct frontend_parse_Expr * self, int line, const char * msg) {
    tool_diag_ct_sem_error(line, 1, msg, self->sup->mem->path);
    tool_diag_ct_sem_note(line, 1, CT_EXPR_CLOSURE_HINT, self->sup->mem->path);
    return (-1);
}
int frontend_parse_closure_copy(struct frontend_parse_Expr * self, const char * * dst, const char * src, const char * what) {
    char msg[512];
    (*dst) = runtime_text_ct_intern(src);
    if ((!(*dst))) {
        snprintf(msg, sizeof(msg), "out of memory while recording a %s", what);
        return self->sup->__frontend_parse_supportops_vptr->fail(self->sup, msg);
    }
    return 0;
}
int frontend_parse_closure_capture_add(struct frontend_parse_Expr * self, int ci, int vi, int line) {
    struct frontend_sym_Closure * c = (&self->sym->closures[ci]);
    const char * name = self->sym->vars[vi].name;
    char msg[512];
    int k;
    if ((self->sym->vars[vi].autodrop || self->sym->vars[vi].borrowed)) {
        snprintf(msg, sizeof(msg), "a closure cannot capture '%s' (it is 'own' or 'borrow')", name);
        return frontend_parse_closure_capture_error(self, line, msg);
    }
    if (self->sym->vars[vi].is_closure) {
        return frontend_parse_closure_capture_error(self, line, "a closure cannot capture another closure");
    }
    if (self->sym->vars[vi].is_array) {
        snprintf(msg, sizeof(msg), "a closure cannot capture the array '%s' (capture a pointer to it instead)", name);
        return frontend_parse_closure_capture_error(self, line, msg);
    }
    if (self->sym->vars[vi].is_slice) {
        snprintf(msg, sizeof(msg), "a closure cannot capture the slice '%s' (a view cannot outlive its array)", name);
        return frontend_parse_closure_capture_error(self, line, msg);
    }
    if (frontend_parse_closure_capture_index(c, name) >= 0) {
        return 0;
    }
    if (c->ncap >= 16) {
        return self->sup->__frontend_parse_supportops_vptr->fail(self->sup, "a closure takes too many captures (limit 16)");
    }
    if (frontend_parse_closure_copy(self, (&c->cap_name[c->ncap]), name, "a captured name") != 0) {
        return (-1);
    }
    if (frontend_parse_closure_copy(self, (&c->cap_type[c->ncap]), self->sym->vars[vi].type, "a captured type") != 0) {
        return (-1);
    }
    c->ncap++;
    for (k = (self->ncl_stack - 2); k >= 0; k--) {
        int oi = self->cl_stack[k];
        struct frontend_sym_Closure * oc = (&self->sym->closures[oi]);
        int j;
        int dup = 0;
        if (vi >= self->cl_pstart[k]) {
            continue;
        }
        for (j = 0; j < oc->ncap; j++) {
            if (strcmp(oc->cap_name[j], name) == 0) {
                dup = 1;
            }
        }
        if (dup) {
            continue;
        }
        if (oc->ncap >= 16) {
            return self->sup->__frontend_parse_supportops_vptr->fail(self->sup, "a closure takes too many captures (limit 16)");
        }
        if (frontend_parse_closure_copy(self, (&oc->cap_name[oc->ncap]), name, "a captured name") != 0) {
            return (-1);
        }
        if (frontend_parse_closure_copy(self, (&oc->cap_type[oc->ncap]), self->sym->vars[vi].type, "a captured type") != 0) {
            return (-1);
        }
        oc->ncap++;
    }
    return 0;
}
int frontend_parse_closure_walk(struct frontend_parse_Expr * self, int ci, int n, int pstart) {
    struct runtime_arena_Node * nd;
    int vi;
    if (n < 0) {
        return 0;
    }
    nd = (&self->arena->nodes[n]);
    if (nd->kind == N_CLOSURE) {
        return 0;
    }
    if (nd->kind == N_CALL) {
        vi = self->sym->__frontend_sym_symbolops_vptr->find_var(self->sym, nd->text2);
        if (((((vi >= 0) && (vi < pstart)) && (!self->sym->vars[vi].is_global)) && self->sym->vars[vi].is_closure)) {
            return frontend_parse_closure_capture_error(self, nd->line, "a closure cannot capture another closure");
        }
    }
    if (nd->kind == N_VAR) {
        vi = self->sym->__frontend_sym_symbolops_vptr->find_var(self->sym, nd->text2);
        if (((vi < 0) || (vi >= pstart))) {
            return 0;
        }
        if (self->sym->vars[vi].is_global) {
            return 0;
        }
        return frontend_parse_closure_capture_add(self, ci, vi, nd->line);
    }
    if (frontend_parse_closure_walk(self, ci, nd->a, pstart) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk(self, ci, nd->b, pstart) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk(self, ci, nd->c, pstart) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk(self, ci, nd->d, pstart) != 0) {
        return (-1);
    }
    return frontend_parse_closure_walk(self, ci, nd->next, pstart);
}
int frontend_parse_closure_walk_shadow(struct frontend_parse_Expr * self, int ci, int n) {
    struct runtime_arena_Node * nd;
    struct frontend_sym_Closure * c = (&self->sym->closures[ci]);
    char msg[512];
    int k;
    if (n < 0) {
        return 0;
    }
    nd = (&self->arena->nodes[n]);
    if (nd->kind == N_CLOSURE) {
        return 0;
    }
    if (nd->kind == N_DECL) {
        for (k = 0; k < c->ncap; k++) {
            if (strcmp(c->cap_name[k], nd->text2) == 0) {
                snprintf(msg, sizeof(msg), "a local cannot shadow the captured '%s'", nd->text2);
                return frontend_parse_closure_capture_error(self, nd->line, msg);
            }
        }
    }
    if (frontend_parse_closure_walk_shadow(self, ci, nd->a) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk_shadow(self, ci, nd->b) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk_shadow(self, ci, nd->c) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk_shadow(self, ci, nd->d) != 0) {
        return (-1);
    }
    return frontend_parse_closure_walk_shadow(self, ci, nd->next);
}
int frontend_parse_closure_walk_mutate(struct frontend_parse_Expr * self, int ci, int n) {
    struct runtime_arena_Node * nd;
    struct frontend_sym_Closure * c = (&self->sym->closures[ci]);
    if (n < 0) {
        return 0;
    }
    nd = (&self->arena->nodes[n]);
    if (nd->kind == N_CLOSURE) {
        return 0;
    }
    if (((((nd->kind == N_ASSIGN) && (nd->a >= 0)) && (self->arena->nodes[nd->a].kind == N_VAR)) && (frontend_parse_closure_capture_index(c, self->arena->nodes[nd->a].text2) >= 0))) {
        return frontend_parse_closure_capture_error(self, self->arena->nodes[nd->a].line, "a captured variable cannot be reassigned inside a closure");
    }
    if ((((((nd->kind == N_PRE) || (nd->kind == N_POST)) && (nd->a >= 0)) && (self->arena->nodes[nd->a].kind == N_VAR)) && (frontend_parse_closure_capture_index(c, self->arena->nodes[nd->a].text2) >= 0))) {
        return frontend_parse_closure_capture_error(self, self->arena->nodes[nd->a].line, "a captured variable cannot be reassigned inside a closure");
    }
    if (((((nd->kind == N_ADDR) && (nd->a >= 0)) && (self->arena->nodes[nd->a].kind == N_VAR)) && (frontend_parse_closure_capture_index(c, self->arena->nodes[nd->a].text2) >= 0))) {
        return frontend_parse_closure_capture_error(self, self->arena->nodes[nd->a].line, "the address of a captured variable cannot be taken inside a closure");
    }
    if (frontend_parse_closure_walk_mutate(self, ci, nd->a) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk_mutate(self, ci, nd->b) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk_mutate(self, ci, nd->c) != 0) {
        return (-1);
    }
    if (frontend_parse_closure_walk_mutate(self, ci, nd->d) != 0) {
        return (-1);
    }
    return frontend_parse_closure_walk_mutate(self, ci, nd->next);
}
